components.css:
.ds-button-primary { display: inline-flex; justify-content: center; align-items: center; gap: 8px; padding: 10px 18px; border: 1px solid transparent; border-radius: var(--radius-control, 7px); background: var(--color-teal, #087c75); color: var(--color-paper, #ffffff); font-family: 'Noto Sans TC', 'Microsoft JhengHei', 'PingFang TC', system-ui, sans-serif; font-size: .87rem; font-weight: 600; line-height: 1.65; min-height: 44px; white-space: nowrap; cursor: pointer; transition: background 160ms ease-out, border-color 160ms ease-out; }
.ds-button-primary:hover { background: var(--color-teal-dark, #08635e); }
.ds-button-primary:disabled { opacity: .5; cursor: not-allowed; }
.ds-button-primary svg { flex-shrink: 0; }
.ds-button-primary:focus-visible { outline: 3px solid var(--color-teal, #087c75); outline-offset: 4px; }
@media (prefers-reduced-motion: reduce) { .ds-button-primary { transition: none !important; animation: none !important; } }

.ds-button-secondary { display: inline-flex; justify-content: center; align-items: center; gap: 8px; padding: 10px 18px; border: 1px solid var(--color-border, #dce5e2); border-radius: var(--radius-control, 7px); background: var(--color-paper, #ffffff); color: var(--color-ink, #183640); font-family: 'Noto Sans TC', 'Microsoft JhengHei', 'PingFang TC', system-ui, sans-serif; font-size: .87rem; font-weight: 600; line-height: 1.65; min-height: 44px; white-space: nowrap; cursor: pointer; transition: background 160ms ease-out, border-color 160ms ease-out; }
.ds-button-secondary:hover { background: var(--color-teal-pale, #e6f3ef); border-color: #b6d7cc; }
.ds-button-secondary:disabled { opacity: .5; cursor: not-allowed; }
.ds-button-secondary svg { flex-shrink: 0; }
.ds-button-secondary:focus-visible { outline: 3px solid var(--color-teal, #087c75); outline-offset: 4px; }
@media (prefers-reduced-motion: reduce) { .ds-button-secondary { transition: none !important; animation: none !important; } }

.ds-button-danger { display: inline-flex; justify-content: center; align-items: center; gap: 8px; padding: 10px 18px; border: 1px solid transparent; border-radius: var(--radius-control, 7px); background: var(--color-danger, #a73333); color: var(--color-paper, #ffffff); font-family: 'Noto Sans TC', 'Microsoft JhengHei', 'PingFang TC', system-ui, sans-serif; font-size: .87rem; font-weight: 600; line-height: 1.65; min-height: 44px; white-space: nowrap; cursor: pointer; transition: background 160ms ease-out, border-color 160ms ease-out; }
.ds-button-danger:hover { background: #862626; }
.ds-button-danger:disabled { opacity: .5; cursor: not-allowed; }
.ds-button-danger svg { flex-shrink: 0; }
.ds-button-danger:focus-visible { outline: 3px solid var(--color-teal, #087c75); outline-offset: 4px; }
@media (prefers-reduced-motion: reduce) { .ds-button-danger { transition: none !important; animation: none !important; } }
